import{z as i,x as B,o as e,c as A,q as l,j as s,D as C,d as r,s as n,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"ECN","description":"","frontmatter":{"title":"ECN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ecn.md","filePath":"cs/ecn.md","lastUpdated":1791063341000}'),d={name:"cs/ecn.md"};function p(c,E,D,T,m,h){const t=B("Mermaid");return e(),A("div",null,[E[2]||(E[2]=l('<h1 id="ecn" tabindex="-1">ECN <a class="header-anchor" href="#ecn" aria-label="Permalink to &quot;ECN&quot;">​</a></h1><div class="epigraph"><p>路由器把 IP 头 CE 位置上，收端在 ACK 里回 ECE，发送方当拥塞处理而不必丢包；要两端与路径都同意。</p><footer>—— 据 RFC 3168；RFC 8311；DCTCP 课对照整理</footer></div><p><a href="/cs/aqm-red-codel">AQM</a> 可以丢也可以标。<a href="/cs/dctcp">DCTCP</a> 已用 CE。<a href="/cs/aqm-red-codel">上一课</a> 留下标记通道。缺口是 <strong>RFC 3168 协商与语义</strong>：ECT、CE、ECE、CWR。本课不把 bufferbloat 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>丢包既是信号也是损伤。ECN：拥塞时标 CE，TCP 用 ECE 通知，发端减窗并回 CWR。握手用 ECN-Echo 与 CWR 位协商能力。中间盒把 CE 清零或丢 ECT 包，则静默失败。L4S 后用不同码点，本课点名。与 PFC：ECN 端到端（路径上最挤跳），PFC 一跳。</p><p><span class="marginnote">直觉类比：丢包像收费站用「扔掉你的车」告诉你前面堵了——信号有效但代价惨重；ECN 像收费员在车窗上贴一张「前方拥堵请减速」的条子，消息照样送到，车也没少一台。对短连接密集的数据中心流量，省下的重传相当可观。</span></p><p>不要把 CE 当成应用错误码。</p><p><span class="marginnote">常见误区：CE（Congestion Experienced）不是给应用看的错误码，而是给 TCP 栈看的拥塞信号，应用完全不感知；它也不表示包损坏——包照常送达，只是顺手捎了一句「路上有点挤」。把它当应用层报错去处理，方向就错了。</span></p><p><span class="marginnote">RFC 3168。Classic ECN 一次拥塞一窗口事件；DCTCP 用比例。本课钉经典语义再对照。</span></p><h3 id="拥塞与丢包分离" tabindex="-1">拥塞与丢包分离 <a class="header-anchor" href="#拥塞与丢包分离" aria-label="Permalink to &quot;拥塞与丢包分离&quot;">​</a></h3><p>CE 沿路径最挤跳；ECE/CWR 走 TCP。中间清洗则静默失败。Classic 一次一事件，DCTCP 用比例。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：ECT 发送 → AQM 标 CE → ECE → MD → CWR。对照无 ECN：丢 → 快重传。QUIC 也有 ECN 计数，后课。</p>',13)),(e(),s(o,null,{default:C(()=>[n(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ECT%5B%22ECT%20%E5%8C%85%22%5D%20--%3E%20CE%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E6%A0%87%20CE%22%5D%0A%20%20CE%20--%3E%20ECE%5B%22ACK%20%E5%B8%A6%20ECE%22%5D%0A%20%20ECE%20--%3E%20MD%5B%22%E5%8F%91%E9%80%81%E6%96%B9%E5%87%8F%E7%AA%97%22%5D%0A%20%20MD%20--%3E%20CWR%5B%22%E9%80%9A%E7%9F%A5%E5%B7%B2%E5%93%8D%E5%BA%94%22%5D%0A"})]),fallback:C(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"ROCE/DCQCN 用 ECN 调速率，不是 TCP ECE。无线链路层丢包不是 CE，后课 TCP 无线会混。PMTUD 与 ECN 正交。安全：伪造 CE 可降速，需路径可信或统计。",-1)),E[5]||(E[5]=a("p",null,"部署：要主机栈、AQMs、不清洗的中间盒同时在。",-1)),E[6]||(E[6]=a("p",null,"一条路径凭什么算「支持 ECN」？任何一环不配合会退到哪里？",-1)),(e(),s(o,null,{default:C(()=>[n(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYN%5B%22%E6%8F%A1%E6%89%8B%E6%97%B6%E5%8D%8F%E5%95%86%20ECN%20%E8%83%BD%E5%8A%9B%22%5D%20--%3E%20BOTH%7B%22%E4%B8%A4%E7%AB%AF%E9%83%BD%E5%90%8C%E6%84%8F%3F%22%7D%0A%20%20BOTH%20--%3E%7C%22%E5%90%A6%22%7C%20OFF%5B%22%E4%B8%8D%E7%94%A8%20ECN%EF%BC%9A%E9%9D%A0%E4%B8%A2%E5%8C%85%E6%8A%A5%E6%8B%A5%E5%A1%9E%22%5D%0A%20%20BOTH%20--%3E%7C%22%E6%98%AF%22%7C%20RUN%5B%22%E6%95%B0%E6%8D%AE%E5%8C%85%E6%A0%87%20ECT%20%E4%B8%8A%E8%B7%AF%22%5D%0A%20%20RUN%20--%3E%20MB%7B%22%E4%B8%AD%E9%97%B4%E7%9B%92%E6%B8%85%E6%B4%97%20CE%20%2F%20%E4%B8%A2%20ECT%3F%22%7D%0A%20%20MB%20--%3E%7C%22%E4%B8%8D%E6%B8%85%E6%B4%97%22%7C%20GOOD%5B%22%E6%8B%A5%E5%A1%9E%E8%B5%B0%E6%A0%87%E8%AE%B0%EF%BC%9A%E4%B8%8D%E4%B8%A2%E5%8C%85%E5%B0%B1%E9%99%8D%E9%80%9F%22%5D%0A%20%20MB%20--%3E%7C%22%E6%B8%85%E6%B4%97%22%7C%20FAIL%5B%22%E9%9D%99%E9%BB%98%E5%A4%B1%E8%B4%A5%EF%BC%9A%E6%A0%87%E8%AE%B0%E5%88%B0%E4%B8%8D%E4%BA%86%E5%8F%91%E7%AB%AF%22%5D%0A%20%20FAIL%20--%3E%20OFF%0A"})]),fallback:C(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 AccECN 的全部。缓冲膨胀是下一课。后课默认：ECN 把拥塞与丢包分离；协商失败则退回丢包信号。</p><p>只在交换机开标记、主机不开，等于没开。</p><p><span class="marginnote">为什么重要：ECN 是端到端合同，任何一环缺席整条失效——中间盒清掉 CE 位，发端永远等不到 ECE，只能退回丢包信号。这也是它提出二十多年仍未全面普及的主因：路径上任何一台不认识它的老设备，都能无声无息地把它废掉。</span></p><p>下一课<a href="/cs/bufferbloat">缓冲膨胀</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CE 是路径拥塞信号，ECE/CWR 走 TCP。</li><li>需端到端支持，中间不可清洗。</li><li>DCTCP 解释不同，码点可同。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 3168；RFC 8311。</li></ul>',7))])}const N=i(d,[["render",p]]);export{f as __pageData,N as default};
